import { writeFileSync } from "node:fs";

const scalar = new Map([
  ["uuid", "string"], ["text", "string"], ["character varying", "string"],
  ["timestamp with time zone", "string"], ["timestamp without time zone", "string"],
  ["date", "string"], ["boolean", "boolean"], ["integer", "number"], ["smallint", "number"],
  ["bigint", "number"], ["numeric", "number"], ["real", "number"], ["double precision", "number"],
  ["json", "Json"], ["jsonb", "Json"], ["bytea", "string"],
]);

export async function schemaTypes(client, schema) {
  const { rows } = await client.query(`
    select c.table_name, c.column_name, c.data_type, c.is_nullable, c.column_default, c.is_identity
    from information_schema.columns c
    join information_schema.tables t using (table_schema, table_name)
    where c.table_schema=$1 and t.table_type='BASE TABLE'
      and c.table_name not in ('_business_migrations', '_business_releases')
    order by c.table_name collate "C", c.column_name collate "C"
  `, [schema]);
  const tables = Map.groupBy(rows, (row) => row.table_name);
  const lines = [
    "// Generated by the trusted schema-types script.", "",
    "export type Json = string | number | boolean | null | Json[] | { [key: string]: Json | undefined };", "",
    "export type Database = {", "  business: {", "    Tables: {",
  ];
  for (const [name, columns] of tables) {
    lines.push(`      ${JSON.stringify(name)}: {`);
    for (const shape of ["Row", "Insert", "Update"]) {
      lines.push(`        ${shape}: {`);
      for (const column of columns) {
        const type = scalar.get(column.data_type);
        if (!type) throw new Error("Add the column type to the trusted type generator");
        const nullable = column.is_nullable === "YES";
        const optional = shape === "Update" ||
          (shape === "Insert" && (nullable || column.column_default !== null || column.is_identity === "YES"));
        lines.push(`          ${JSON.stringify(column.column_name)}${optional ? "?" : ""}: ${type}${nullable ? " | null" : ""};`);
      }
      lines.push("        };");
    }
    lines.push("      };");
  }
  lines.push("    };", "  };", "};", "");
  return lines.join("\n");
}

export async function writeSchemaTypes(client, schema, destination) {
  const expected = await schemaTypes(client, schema);
  writeFileSync(destination, expected);
  return expected;
}
